SELECT 
FROM ydsz_flow_his_task
WHERE status = 'ENABLED'
  AND deleted = 0
  AND assignee_id = #{assigneeId}
  AND business_type = #{businessType}
  AND flow_code = #{flowCode}
  AND finish_at >= #{startTime}
  AND finish_at <= #{endTime}
  AND tenant_id = #{tenantId}
ORDER BY finish_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM ydsz_flow_his_task
WHERE status = 'ENABLED'
  AND deleted = 0
  AND assignee_id = #{assigneeId}
  AND business_type = #{businessType}
  AND flow_code = #{flowCode}
  AND finish_at >= #{startTime}
  AND finish_at <= #{endTime}
  AND tenant_id = #{tenantId}
